/**
 * TrustChat provider plugin for OpenCode V2.
 *
 * Adds:
 *  - a "TrustChat" entry to /connect (API key or TRUSTCHAT_API_KEY);
 *  - an OpenAI-compatible provider that discovers models from /v1/models;
 *  - model metadata (names, modalities, limits, reasoning field) from the
 *    models.dev catalog, cached on disk and refreshed in the background.
 *
 * OpenCode 1.x is not supported: the plugin ships a `./server` entrypoint and a
 * `main` shim (`v1-unsupported.ts`) that only report an explicit error.
 */

import { isAbsolute } from "node:path"

import {
  catalogStats,
  createCatalogSource,
  resolveCatalogEntry,
  resolveModelMeta,
  type Catalog,
  type CatalogSnapshot,
  type CatalogSource,
  type ModelMeta,
} from "./models-dev.ts"
import {
  isRecord,
  nonEmptyString,
  readCacheFile,
  resolveCachePath,
  writeCacheFile,
} from "./disk-cache.ts"
import {
  sanitizeMessage,
  TrustChatRpc,
  type ReloadResult,
  type StatusSnapshot,
} from "./rpc.ts"

const PROVIDER_ID = "trustchat"
const PROVIDER_NAME = "TrustChat"
const PROVIDER_PACKAGE = "@opencode/ai/providers/openai-compatible"
const DEFAULT_BASE_URL = "https://trustchat.wb-bank.ru:8443/v1"
const DEFAULT_CATALOG_URL = "https://models.dev/models.json"
const MODELS_TIMEOUT_MS = 15_000
const EVENT_REFRESH_THROTTLE_MS = 5_000
/** Next periodic /v1/models attempt after a successful one. */
export const MODEL_REFRESH_SUCCESS_MS = 30 * 60_000
/** Next periodic /v1/models attempt after a failed one (also "no credential"). */
export const MODEL_REFRESH_FAILURE_MS = 60_000
const HEALTH_TIMEOUT_MS = 2_000
const TOAST_DURATION_MS = 15_000

// Last successful GET /v1/models list, next to the models.dev cache. The
// payload holds already-normalized entries ({ id, created }), never the raw
// HTTP body, so a corrupt/updated upstream shape cannot confuse a restart.
const MODEL_LIST_CACHE_FILE = "models-list.json"
const MODEL_LIST_CACHE_VERSION = 1
const MODEL_LIST_CACHE_MAX_BYTES = 2 * 1024 * 1024

// The only built-in metadata left: used when the catalog is disabled, has no
// match for a model, or has not been cached yet. The display name in that case
// is the raw basename (the last id segment).
const DEFAULT_MODEL = {
  context: 1_048_576,
  output: 128_000,
  input: ["text"],
}

function normalizeBaseURL(value: unknown): string {
  const raw = typeof value === "string" && value.trim() ? value.trim() : DEFAULT_BASE_URL
  return raw.replace(/\/+$/, "")
}

function modelIDOf(value: unknown): string | undefined {
  if (typeof value === "string") return value.trim() || undefined
  if (value && typeof value === "object" && "id" in value && typeof value.id === "string") {
    return value.id.trim() || undefined
  }
  return undefined
}

// Model ids look like "<model>", "<role>/<model>", "<role>/<variant>/<model>"
// or deeper. Whatever the depth, the model basename is the LAST
// "/"-separated segment, and the variant is the segment right before it, so
// "a/b/c" has role "a", variant "b" and model "c", while "a/b/c/d" keeps only
// role "a" and variant "c" next to model "d". Empty segments parse the same
// way ("a//m" has an empty variant); which of them end up in a display-name
// suffix is decided per basename group in groupSuffixParts, not here.
function splitModelID(id: string): { role?: string; variant?: string; model: string } {
  const segments = id.split("/")
  return {
    ...(segments.length >= 2 ? { role: segments[0] } : {}),
    ...(segments.length >= 3 ? { variant: segments[segments.length - 2] } : {}),
    model: segments[segments.length - 1],
  }
}

/** Shapes accepted as a model list: an array, or an object with an array field. */
function modelEntries(payload: any): unknown[] | undefined {
  if (Array.isArray(payload)) return payload
  if (Array.isArray(payload?.data)) return payload.data
  if (Array.isArray(payload?.models)) return payload.models
  return undefined
}

function tokenOf(credential: any): string | undefined {
  if (!credential || typeof credential !== "object") return undefined
  if (credential.type === "key" && typeof credential.key === "string") return credential.key
  if (credential.type === "oauth" && typeof credential.access === "string") return credential.access
  return undefined
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/* ------------------------------------------------------------------ */
/* OpenCode 1.x guard                                                  */
/* ------------------------------------------------------------------ */

/** Message shown when the plugin is loaded by an unsupported OpenCode 1.x. */
export function unsupportedVersionMessage(version?: string): string {
  return (
    "@trustchat/opencode-provider требует OpenCode V2. " +
    `OpenCode 1.x${version ? ` (${version})` : ""} не поддерживается: ` +
    'обновите OpenCode до 2.x и используйте ключ "plugins" вместо "plugin".'
  )
}

/** Reads `{ version }` from the 1.x `/global/health` endpoint. Never throws. */
async function healthVersion(input: any): Promise<string | undefined> {
  const serverUrl = input?.serverUrl
  if (!serverUrl) return undefined

  try {
    const response = await fetch(new URL("/global/health", String(serverUrl)), {
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(HEALTH_TIMEOUT_MS),
    })
    if (!response.ok) return undefined
    const payload: unknown = await response.json()
    const version =
      payload && typeof payload === "object" ? (payload as { version?: unknown }).version : undefined
    return typeof version === "string" && version.trim() ? version.trim() : undefined
  } catch {
    return undefined
  }
}

/**
 * Reports that the plugin runs on an unsupported OpenCode 1.x and returns an
 * empty hooks object. Used by both the `server()` entrypoint and the `main`
 * shim, so 1.x shows the same message whichever entrypoint it resolves.
 *
 * Every channel is attempted in turn and guarded: a 1.x client may be missing
 * TUI methods (headless server) or fail on an unknown route.
 */
export async function reportUnsupported(input: any): Promise<Record<string, never>> {
  const message = unsupportedVersionMessage(await healthVersion(input))

  try {
    await input?.client?.app?.log({ body: { service: PROVIDER_ID, level: "error", message } })
  } catch {}

  try {
    await input?.client?.tui?.showToast({
      body: {
        title: PROVIDER_NAME,
        message,
        variant: "error",
        duration: TOAST_DURATION_MS,
      },
    })
  } catch {}

  try {
    console.error(`[trustchat] ${message}`)
  } catch {}

  return {}
}

/* ------------------------------------------------------------------ */
/* Options                                                             */
/* ------------------------------------------------------------------ */

interface ModelsDevOptions {
  enabled: boolean
  url: string
  /** Absolute path override for the disk cache. */
  cacheFile?: string
}

interface PluginOptions {
  /** Base URL of the OpenAI-compatible API. */
  baseURL?: string
  modelsDev?: ModelsDevOptions
}

function parseModelsDevOptions(
  value: unknown,
  warn: (...args: unknown[]) => void,
): ModelsDevOptions {
  const result: ModelsDevOptions = {
    enabled: true,
    url: DEFAULT_CATALOG_URL,
  }

  if (value === undefined) return result
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    warn("ignoring modelsDev option: expected an object")
    return result
  }

  const record = value as Record<string, unknown>

  if (typeof record.enabled === "boolean") result.enabled = record.enabled
  else if (record.enabled !== undefined) warn("ignoring modelsDev.enabled: expected a boolean")

  if (typeof record.url === "string" && /^https?:\/\/\S+$/i.test(record.url.trim())) {
    result.url = record.url.trim()
  } else if (record.url !== undefined) {
    warn("ignoring modelsDev.url: expected an http(s) URL")
  }

  if (typeof record.cacheFile === "string" && record.cacheFile.trim()) {
    const cacheFile = record.cacheFile.trim()
    if (isAbsolute(cacheFile)) result.cacheFile = cacheFile
    else warn("ignoring modelsDev.cacheFile: expected an absolute path")
  } else if (record.cacheFile !== undefined) {
    warn("ignoring modelsDev.cacheFile: expected an absolute path")
  }

  return result
}

/* ------------------------------------------------------------------ */
/* Model building                                                      */
/* ------------------------------------------------------------------ */

interface RawModelEntry {
  id: string
  parsed: { role?: string; variant?: string; model: string }
  created: number
}

interface BuildContext {
  /** Basenames already reported as unmatched; keeps rebuilds quiet. */
  warnedBasenames: Set<string>
  logDebug: (...args: unknown[]) => void
  logWarn: (...args: unknown[]) => void
}

function rawModelEntries(entries: unknown[]): RawModelEntry[] {
  const seen = new Set<string>()
  const result: RawModelEntry[] = []

  for (const entry of entries) {
    const id = modelIDOf(entry)
    if (!id || seen.has(id)) continue
    seen.add(id)

    const record = entry && typeof entry === "object" ? (entry as any) : {}
    const created =
      typeof record.created === "number" && Number.isFinite(record.created) ? record.created : 0

    result.push({ id, parsed: splitModelID(id), created })
  }

  result.sort((a, b) => a.id.localeCompare(b.id))
  return result
}

/** One basename group: every model id whose last segment is the same. */
interface BasenameGroup {
  /**
   * Group members in sorted-id order (see rawModelEntries). The suffix of one
   * member depends on the suffixes of all the others, so every entry is kept.
   */
  entries: RawModelEntry[]
}

/**
 * Groups the entries by basename (the last id segment, compared exactly and
 * case-sensitively). The membership — not just a count — is what the naming
 * ladder needs: whether the basename is unique, and which suffixes collide.
 */
function basenameGroups(entries: RawModelEntry[]): Map<string, BasenameGroup> {
  const groups = new Map<string, BasenameGroup>()
  for (const entry of entries) {
    const group = groups.get(entry.parsed.model)
    if (group) group.entries.push(entry)
    else groups.set(entry.parsed.model, { entries: [entry] })
  }
  return groups
}

/** Reasoning levels exposed for models with `reasoning: true` in the catalog. */
const REASONING_EFFORTS = ["none", "low", "high", "max"] as const

function reasoningVariants(): any[] {
  return REASONING_EFFORTS.map((effort) => ({
    id: effort,
    settings: { reasoningEffort: effort },
  }))
}

/** Mutable suffix state of one group member while collisions are resolved. */
interface SuffixCandidate {
  entry: RawModelEntry
  /** The id without its basename, left to right. */
  prefix: string[]
  /** 2-segment ids: the role is the only suffix and is always shown. */
  fixed: boolean
  /** Trailing prefix segments in the suffix; 0 means "no suffix". */
  size: number
}

/** Current suffix parts of a candidate, with empty segments dropped. */
function suffixParts(candidate: SuffixCandidate): string[] {
  if (candidate.size === 0) return []
  return candidate.prefix
    .slice(-candidate.size)
    .filter((part) => part !== "")
}

/** A 3+ segment candidate may still grow, up to its full prefix. */
function canGrow(candidate: SuffixCandidate): boolean {
  return !candidate.fixed && candidate.size > 0 && candidate.size < candidate.prefix.length
}

/** Grows the suffix one step, skipping over empty segments. */
function grow(candidate: SuffixCandidate): void {
  if (!canGrow(candidate)) return
  candidate.size += 1
  while (candidate.size < candidate.prefix.length && suffixParts(candidate).length === 0) {
    candidate.size += 1
  }
}

/**
 * Suffix parts for every member of one basename group — the "minimal suffix
 * ladder":
 *
 * - "<model>" (1 segment): never suffixed;
 * - "<role>/<model>" (2 segments): the role, always, even when the basename is
 *   unique in the group;
 * - 3+ segments: nothing while the basename is unique; once the group has two
 *   or more members, the shortest right-anchored suffix — 1 segment ("b"),
 *   then 2 ("a/b"), then 3, ... up to the full prefix ("a/b/c").
 *
 * Collisions are resolved one step at a time: every member whose suffix equals
 * another member's suffix grows by one segment, while 2-segment members stay at
 * their role and 1-segment members stay unsuffixed. Repeating the pass until no
 * collisions remain yields the minimal length each member needs, and different
 * members may settle at different lengths (e.g. "a/x/m" + "b/y/m" + "c/x/m" →
 * "a/x", "y", "c/x").
 *
 * Termination: every change strictly increases one member's suffix length and
 * no member grows past its full prefix, so the loop is bounded. Distinct ids
 * have distinct full prefixes, so a fixed point exists — except when filtered
 * empty segments collapse two prefixes onto the same non-empty suffix. Then the
 * shortest reachable suffix wins and the display names can coincide while the
 * unique ids still tell the models apart.
 *
 * Empty segments never join a suffix, so "a//m" escalates instead of yielding
 * " ()" or " (a/)"; a suffix that stays empty is dropped entirely.
 */
function groupSuffixParts(group: BasenameGroup): Map<string, string> {
  const unique = group.entries.length === 1
  const members: SuffixCandidate[] = group.entries.map((entry) => {
    const prefix = entry.id.split("/").slice(0, -1)
    let size = 1
    if (prefix.length === 0) size = 0
    else if (prefix.length >= 2 && unique) size = 0
    return { entry, prefix, fixed: prefix.length === 1, size }
  })

  // Start at a non-empty suffix: "a//m" begins at k=2 and gets " (a)".
  for (const member of members) {
    if (suffixParts(member).length === 0) grow(member)
  }

  for (;;) {
    const counts = new Map<string, number>()
    for (const member of members) {
      const key = suffixParts(member).join("/")
      counts.set(key, (counts.get(key) ?? 0) + 1)
    }

    let changed = false
    for (const member of members) {
      const key = suffixParts(member).join("/")
      // An empty suffix is a guard, not a collision that can be resolved.
      if (!key || (counts.get(key) ?? 0) < 2 || !canGrow(member)) continue
      grow(member)
      changed = true
    }
    if (!changed) break
  }

  const result = new Map<string, string>()
  for (const member of members) {
    const parts = suffixParts(member)
    if (parts.length > 0) result.set(member.entry.id, parts.join("/"))
  }
  return result
}

/** Formats the " (<parts>)" display-name suffix for every member with one. */
function modelSuffixes(groups: Map<string, BasenameGroup>): Map<string, string> {
  const suffixes = new Map<string, string>()
  for (const group of groups.values()) {
    for (const [id, parts] of groupSuffixParts(group)) suffixes.set(id, ` (${parts})`)
  }
  return suffixes
}

/**
 * Converts one /v1/models entry into an OpenCode V2 runtime model.
 *
 * `enabled` is the caller-computed catalog default (see buildModels): it must
 * go into the runtime `enabled` field, because OpenCode does not read a
 * `disabled` field on the model object. The config-level
 * `providers.trustchat.models.<id>.disabled` flag is translated to `enabled`
 * and applied after this plugin, so users can override the default either way.
 */
function toModel(
