    // `settings.reasoningEffort` into `reasoning_effort` in the request body.
    variants: meta.reasoning ? reasoningVariants() : [],
    time: { released: meta.released },
    // TrustChat has its own billing, so catalog prices must not leak here.
    cost: [],
    status: "active",
    enabled,
    limit: {
      c
