/* ------------------------------------------------------------------ */
/* Model list cache                                                    */
/* ------------------------------------------------------------------ */

interface ModelListCachePayload {
  version: number
  fetchedAt: number
  entries: { id: string; created: number }[]
}

/** Validated contents of `models-list.json`. */
interface ModelListCache {
  entries: unknown[]
  /** `fetchedAt` of the file, or null when it is absent/not a finite number. */
  fetchedAt: number | null
}

/** Normalized entries, so the cache never stores the raw HTTP body. */
function cacheEntries(entries: unknown[]): { id: string; created: number }[] {
  return rawModelEntries(entries).map(({ id, created }) => ({ id, created }))
}

/**
 * Validates a `models-list.json` payload. Returns `undefined` for a wrong
 * version/shape (behave as if there were no cache) and a cache with an empty
 * entry list for a legitimately empty cached list (a successful empty 200 from
 * a previous run).
 */
function parseModelListCache(raw: string): ModelListCache | undefined {
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    return undefined
  }

  if (!isRecord(parsed)) return undefined
  if (parsed.version !== MODEL_LIST_CACHE_VERSION) return undefined
  if (!Array.isArray(parsed.entries)) return undefined

  const entries: { id: string; created: number }[] = []
  for (const item of parsed.entries) {
    if (!isRecord(item)) continue
    const id = nonEmptyString(item.id)
    if (!id) continue
    const created =
      typeof item.created === "number" && Number.isFinite(item.created) ? item.created : 0
    entries.push({ id, created })
  }

  const fetchedAt =
    typeof parsed.fetchedAt === "number" && Number.isFinite(parsed.fetchedAt)
      ? parsed.fetchedAt
      : null

  return { entries, fetchedAt }
}

/* ------------------------------------------------------------------ */
/* Periodic model-list refresh                                         */
/* ------------------------------------------------------------------ */

/**
 * Outcome of one `/v1/models` attempt. Missing connection/credential counts as
 * a failure: there is no list to refresh yet, so a retry in a minute is exactly
 * what a later `/connect` needs.
 */
export type RefreshOutcome = boolean

/**
 * What started an attempt: the periodic timer, an integration/credential event
 * or a manual refresh. `startup` is the first background attempt; it does not
 * consume the event throttle window, so an early `/connect` event is still
 * picked up immediately.
 */
export type RefreshTrigger = "timer" | "manual" | "startup"

export interface RefreshSchedulerTimer {
  /** Node's `unref`, when the host timer object has one. */
  unref?: () => void
}

export interface RefreshSchedulerOptions {
  /** One complete attempt (including any trailing pass); resolves to success. */
  attempt: (trigger: RefreshTrigger) => Promise<RefreshOutcome>
  /** Test seam: defaults to the global `setTimeout`. */
  setTimeoutImpl?: (callback: () => void, ms: number) => RefreshSchedulerTimer
  /** Test seam: defaults to the global `clearTimeout`. */
  clearTimeoutImpl?: (handle: RefreshSchedulerTimer) => void
  /** Test seam: override the success delay. */
  successDelayMs?: number
  /** Test seam: override the failure delay. */
  failureDelayMs?: number
  /** Called when an attempt rejects unexpectedly (the cycle keeps going). */
  onError?: (error: unknown) => void
}

export interface RefreshScheduler {
  /** Schedule the next attempt for this outcome, replacing any pending timer. */
  schedule: (outcome: RefreshOutcome) => void
  /** Run one attempt now, then reschedule from its outcome. */
  run: (trigger?: RefreshTrigger) => Promise<RefreshOutcome>
  /** Armed deadline of the pending attempt, or null when no timer is pending. */
  nextAt: () => number | null
  /** Cancel the timer; no later attempt is scheduled or started. */
  dispose: () => void
}

/**
 * Single self-rescheduling timer for the `/v1/models` poll.
 *
 * The invariant is structural: a timer is created only in `schedule()`, which
 * is called after an attempt settles (or once at startup), and `schedule()`
 * first clears the previous handle. `run()` is shared by the timer and by
 * `integration.*`/`credential.*` events, so either kind of attempt drives the
 * same cycle: success → 30 min, failure → 1 min. The trigger is passed through
 * so a timer tick landing on an in-flight attempt does not ask for a redundant
 * trailing pass (an event still does).
 */
export function createRefreshScheduler(options: RefreshSchedulerOptions): RefreshScheduler {
  const setT =
    options.setTimeoutImpl ??
    ((callback: () => void, ms: number) =>
      setTimeout(callback, ms) as unknown as RefreshSchedulerTimer)
  const clearT =
    options.clearTimeoutImpl ??
    ((handle: RefreshSchedulerTimer) => clearTimeout(handle as any))
  const successDelay = options.successDelayMs ?? MODEL_REFRESH_SUCCESS_MS
  const failureDelay = options.failureDelayMs ?? MODEL_REFRESH_FAILURE_MS
  const onError = options.onError ?? (() => {})

  let timer: RefreshSchedulerTimer | undefined
  let nextPollAt: number | null = null
  let disposed = false

  const cancel = () => {
    nextPollAt = null
    if (timer === undefined) return
    clearT(timer)
    timer = undefined
  }

  const schedule = (outcome: RefreshOutcome) => {
    if (disposed) return
    cancel()
    const delay = outcome ? successDelay : failureDelay
    const handle = setT(() => {
      timer = undefined
      void run("timer")
    }, delay)
    timer = handle
    nextPollAt = Date.now() + delay
    // Never keep an idle process alive just for the poll.
    if (typeof handle?.unref === "function") handle.unref()
  }

  const run = async (trigger: RefreshTrigger = "manual"): Promise<RefreshOutcome> => {
    if (disposed) return false
    // The armed poll is intentionally left in place while the attempt runs:
    // it is a deadline, not a second scheduling path, and a timer tick landing
    // on an in-flight attempt reuses it (see the coalescing in index.ts).
    // `schedule()` replaces it once the outcome is known.
    let outcome = false
    try {
      outcome = await options.attempt(trigger)
    } catch (error) {
      onError(error)
    }
    // An attempt may settle after dispose; do not revive the cycle then.
    schedule(outcome)
    return outcome
  }

  return {
    schedule,
    run,
    nextAt: () => (disposed ? null : nextPollAt),
    dispose: () => {
      disposed = true
      cancel()
    },
  }
}

/* ------------------------------------------------------------------ */
/* Plugin                                                              */
/* ------------------------------------------------------------------ */

export default {
  id: PROVIDER_ID,

  /**
   * OpenCode 1.x entrypoint (`exports["./server"]`). V2 ignores it and uses
   * `setup()`; 1.x calls it and gets an explicit "not supported" report
   * instead of a silent no-op.
   */
  async server(input: any): Promise<Record<string, never>> {
    return reportUnsupported(input)
  },

  async setup(ctx: any) {
    const version = ctx?.app?.version
    const major = Number.parseInt(String(version ?? ""), 10)
    if (Number.isFinite(major) && major < 2) {
      throw new Error(unsupportedVersionMessage(String(version)))
    }

    const options: PluginOptions = ctx.options ?? {}
    const baseURL = normalizeBaseURL(options.baseURL)

    c
