    }

    // Boolean-coalescing: at most one refresh runs at a time. An event that
    // arrives during a run triggers exactly one more pass; a timer tick that
    // lands on an in-flight run does not (the run already covers it), so a
    // poll never causes a redundant trailing fetch.
    const runRefresh = (trigger: RefreshTrigger): Promise<RefreshOutcome> => {
      if (running) {
        if (trigger === "manual") queued = true
        return running
      }

      running = (async (): Promise<RefreshOutcome> => {
        let outcome: RefreshOutcome = false
        do {
          queued = false
          outcome = await refresh(trigger)
        } while (queued && !disposed)
        return outcome
      })()
        .catch((error) => {
          lastRefreshError = sanitizeMessage(errorMessage(error))
          lastAttemptAt = Date.now()
          lastAttemptKind =
            error instanceof ModelsFetchError && error.kind === "unauthorized"
              ? "unauthorized"
              : "unavailable"
          logError("refresh failed:", errorMessage(error))
          return false
        })
        .finally(() => {
          running = undefined
        })

      return running
    }

    // One self-rescheduling timer drives the periodic /v1/models poll. Events
    // and the timer both go through runRefresh, so whichever attempt settles
    // decides the next delay — 30 min after success, 1 min after a failure —
    // and there is never more than one pending timer.
    const scheduler = createRefreshScheduler({
      attempt: runRefresh,
      onError: (error) => logError("refresh failed:", errorMessage(error)),
    })

    // The first network attempt is deliberately NOT awaited here. Plugin
    // discovery has a short budget (~10 s) while a blackholed endpoint can hold
    // `/v1/models` for MODELS_TIMEOUT_MS (15 s): setup() must return with the
    // provider and the RPC already registered from the cached list, otherwise
    // the desktop status panel and `reload` never become available.
    // The background attempt still goes through runRefresh (the same
    // coalescing as timers/events) and its outcome arms the 30 min / 1 min
    // deadline. `scheduler.run` never rejects and checks dispose itself.

    /* ------------------------------------------------------------------ */
    /* Status / reload RPC                                                 */
    /* ------------------------------------------------------------------ */

    /** ISO 8601 UTC string for a process-local timestamp; null stays null. */
    const isoTimestamp = (value: number | null): string | null =>
      value === null ? null : new Date(value).toISOString()

    /**
     * JSON-safe snapshot for the `status` RPC.
     *
     * `status` follows the latest completed `/v1/models` attempt: no attempt
     * yet (or a successful one) is "ok"; a missing credential, an HTTP 401 and
     * every other failure are "error". The credential comes from the same
     * resolution the fetch path uses; the token value is never returned. A
     * credential lookup failure is reported as "not configured" instead of
     * failing the whole status call.
     */
    const statusSnapshot = async (): Promise<StatusSnapshot> => {
      let token: string | undefined
      try {
        token = (await credentialState()).token
      } catch (error) {
        logDebug("status: credential resolution failed:", errorMessage(error))
      }

      const models_total_count = models.length
      const models_enabled_count = models.filter((model: any) => model?.enabled === true).length

      const timestamps = {
        models_enabled_count,
        models_total_count,
        models_last_success_sync: isoTimestamp(lastSuccessAt),
        models_last_sync: isoTimestamp(lastAttemptAt),
        models_next_sync: isoTimestamp(scheduler.nextAt()),
      }

      if (token === undefined) {
        return { status: "error", error: "Ключ не настроен", ...timestamps }
      }

      if (lastAttemptKind === "unauthorized") {
        return { status: "error", error: "Неверный ключ", ...timestamps }
      }

      if (lastAttemptKind === "unavailable") {
        return {
          status: "error",
          error: `Ошибка: ${lastRefreshError ?? "не удалось обновить список моделей"}`,
          ...timestamps,
        }
      }

      return { status: "ok", error: null, ...timestamps }
    }

    /**
     * `reload`: one attempt through the same scheduler the timer and events
     * use. The scheduler serializes it with any in-flight refresh and
     * reschedules the poll from the outcome, so no second scheduling path
     * exists. A failure keeps the previous list (refreshModels only replaces it
     * after a successful 200) and arms the usual 1-minute retry.
     */
    const reloadModels = async (): Promise<ReloadResult> => {
      lastRefreshError = undefined
      const ok = await scheduler.run("manual")
      if (ok) return { ok: true, modelCount: models.length }
      return {
        ok: false,
        modelCount: models.length,
        error: lastRefreshError ?? "не удалось обновить список моделей",
      }
    }

    // Older 2.x builds may not expose `ctx.rpc`: the provider keeps working,
    // only the desktop status panel reports an error. Registration failures are
    // equally non-fatal.
    let rpcRegistration: { dispose: () => Promise<void> } | undefined
    if (typeof ctx.rpc?.register === "function") {
      try {
        rpcRegistration = await ctx.rpc.register(TrustChatRpc, {
          status: async () => statusSnapshot(),
          reload: async () => reloadModels(),
        })
      } catch (error) {
        logWarn("rpc: registration failed:", errorMessage(error))
      }
    } else {
      logDebug("rpc: ctx.rpc.register is unavailable; the status panel is disabled")
    }

    // Start polling only after the provider transform and the RPC are in
    // place. Without a connection the attempt returns immediately and the
    // cycle retries in a minute, so a later /connect is picked up even if no
    // event arrives.
    void scheduler
      .run("startup")
      .catch((error) => logError("startup refresh failed:", errorMessage(error)))

    // The catalog is fetched in the background: cached metadata is used for the
    // first /v1/models pass, then models are rebuilt if the catalog changed.
    if (catalogSource) void refreshCatalog()

    // Events are throttled: trustchat never re-reads /v1/models more often than
    // once per EVENT_REFRESH_THROTTLE_MS, but a burst still leads to one final
    // refresh so a key entered via /connect is picked up.
    const scheduleRefresh = () => {
      const wait = EVENT_REFRESH_THROTTLE_MS - (Date.now() - lastEventRefreshAt)
      if (wait <= 0) {
        void scheduler.run()
        return
      }
      if (scheduledRefresh) return
      scheduledRefresh = setTimeout(() => {
        scheduledRefresh = undefined
        void scheduler.run()
      }, wait)
    }

    const controller = new AbortController()
    void (async () => {
      try {
        for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
          const type = typeof event?.type === "string" ? event.type : ""
          if (!type.startsWith("integration.") && !type.startsWith("credential.")) continue
          scheduleRefresh()
        }
      } catch (error) {
        if (!controller.signal.aborted) logError("event stream failed:", error)
      }
    })()

    return async () => {
      disposed = true
      scheduler.dispose()
      controller.abort()
      if (scheduledRefresh) {
        clearTimeout(scheduledRefresh)
        scheduledRefresh = undefined
      }
      if (rpcRegistration && typeof rpcRegistration.dispose === "function") {
        try {
          await rpcRegistration.dispose()
        } catch (error) {
          logWarn("rpc: dispose failed:", errorMessage(error))
        }
      }
    }
  },
}
